<?php
namespace App\Http\Controllers;
use App\Models\User;use App\Services\AuditService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;
class AuthController extends Controller {public function show(){return view('auth.login');}public function login(Request $request){$data=$request->validate(['email'=>['required','email'],'password'=>['required','string'],'remember'=>['nullable','boolean']]);if(!Auth::attempt(['email'=>$data['email'],'password'=>$data['password']],$request->boolean('remember'))){return back()->withErrors(['email'=>'Invalid email or password.'])->onlyInput('email');}$request->session()->regenerate();app(AuditService::class)->record($request->user(),'login',$request->user());return redirect()->route($request->user()->role.'.dashboard');}public function logout(Request $request){app(AuditService::class)->record($request->user(),'logout',$request->user());Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('login');}}
